exec 2>>/run/bsl-sshfs.log 3<&0; u='tester'; m='/mnt/host'; uid=$(id -u "$u") || exit 3; gid=$(id -g "$u") || exit 3; mountpoint -q "$m" && umount -l "$m"; mkdir -p "$m"; sshfs -f -o passive,allow_other,default_permissions,uid=$uid,gid=$gid,dcache_timeout=5 breadstick:/ "$m" <&3 & p=$!; trap 'umount -l "$m"; kill $p' HUP TERM; wait $p; st=$?; mountpoint -q "$m" && umount -l "$m"; exit $st
